<?php
require_once 'config/database.php';require_once 'includes/functions.php';verifyCsrf();$errors=[];$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 $mode=$_POST['mode']??'';
 if($mode==='delete'){try{$q=$pdo->prepare("DELETE FROM categories WHERE id=?");$q->execute([(int)$_POST['id']]);flash('success','Kategori berhasil dihapus.');}catch(PDOException $e){flash('error','Kategori masih digunakan oleh produk. Pindahkan produk terlebih dahulu.');}redirect('categories.php');}
 if($mode==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');if(!$name)$errors[]='Nama kategori wajib diisi.';$q=$pdo->prepare("SELECT id FROM categories WHERE name=? AND id<>?");$q->execute([$name,$id]);if($q->fetch())$errors[]='Nama kategori sudah ada.';if(!$errors){if($id){$q=$pdo->prepare("UPDATE categories SET name=?,description=? WHERE id=?");$q->execute([$name,$description,$id]);flash('success','Kategori diperbarui.');}else{$q=$pdo->prepare("INSERT INTO categories(name,description) VALUES(?,?)");$q->execute([$name,$description]);flash('success','Kategori ditambahkan.');}redirect('categories.php');}$edit=$_POST;}
}
if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM categories WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$cats=$pdo->query("SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name")->fetchAll();
$pageTitle='Kategori Produk';require 'includes/header.php';?>
<div class="page-tools"><p class="muted">Atur pengelompokan produk agar inventaris lebih rapi.</p></div>
<div class="two-column">
<section class="form-panel"><div class="panel-head"><div><span class="eyebrow">CATEGORY FORM</span><h3><?= $edit?'Edit Kategori':'Tambah Kategori' ?></h3></div></div><?php if($errors): ?><div class="alert error"><?= implode('<br>',array_map('e',$errors)) ?></div><?php endif; ?>
<form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="mode" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Nama Kategori<input required name="name" value="<?= e($edit['name']??'') ?>" placeholder="Contoh: Shoe Cleaner"></label><label>Deskripsi<textarea name="description" rows="4" placeholder="Keterangan kategori..."><?= e($edit['description']??'') ?></textarea></label><button class="btn btn-primary"><?= $edit?'Simpan Perubahan':'Tambah Kategori' ?></button><?php if($edit): ?><a class="btn btn-outline" href="categories.php">Batal</a><?php endif; ?></form></section>
<section class="panel"><div class="panel-head"><div><span class="eyebrow">CATEGORY LIST</span><h3>Daftar Kategori</h3></div><span class="count-chip"><?= count($cats) ?> kategori</span></div><div class="category-list"><?php foreach($cats as $c): ?><div class="category-row"><div class="category-symbol">◫</div><div class="category-info"><strong><?= e($c['name']) ?></strong><small><?= e($c['description']?:'Tanpa deskripsi') ?></small><small><?= (int)$c['product_count'] ?> produk</small></div><div class="action-group"><a class="icon-btn" href="categories.php?edit=<?= $c['id'] ?>">✎</a><form method="post" onsubmit="return confirm('Hapus kategori ini?')"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="mode" value="delete"><input type="hidden" name="id" value="<?= $c['id'] ?>"><button class="icon-btn danger">×</button></form></div></div><?php endforeach; ?><?php if(!$cats): ?><div class="empty-state compact">Belum ada kategori.</div><?php endif; ?></div></section></div>
<?php require 'includes/footer.php'; ?>
